"""Postgres schema for reference records and the agent's operational state."""

from __future__ import annotations

from datetime import date, datetime
from decimal import Decimal
from typing import Any
from uuid import uuid4

from sqlalchemy import (
    BigInteger, CheckConstraint, Date, DateTime, ForeignKey, Index, Integer,
    String, Text, Numeric, UniqueConstraint, func,
)
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column


class Base(DeclarativeBase):
    pass


class RiderModel(Base):
    __tablename__ = "riders"

    rider_id: Mapped[str] = mapped_column(String(64), primary_key=True)
    name: Mapped[str] = mapped_column(String(160), nullable=False)
    city: Mapped[str] = mapped_column(String(120), nullable=False)
    joined_on: Mapped[date] = mapped_column(Date, nullable=False)


class TripModel(Base):
    __tablename__ = "trips"
    __table_args__ = (Index("ix_trips_rider_started_at", "rider_id", "started_at"),)

    trip_id: Mapped[str] = mapped_column(String(64), primary_key=True)
    rider_id: Mapped[str] = mapped_column(ForeignKey("riders.rider_id"), nullable=False)
    started_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    status: Mapped[str] = mapped_column(String(32), nullable=False)
    distance_km: Mapped[Decimal] = mapped_column(Numeric(10, 3), nullable=False)
    surge_multiplier: Mapped[Decimal] = mapped_column(Numeric(8, 3), nullable=False)


class PayoutLineModel(Base):
    __tablename__ = "payout_lines"
    __table_args__ = (Index("ix_payout_lines_rider_date", "rider_id", "payout_date"),)

    line_id: Mapped[str] = mapped_column(String(64), primary_key=True)
    payout_date: Mapped[date] = mapped_column(Date, nullable=False)
    rider_id: Mapped[str] = mapped_column(ForeignKey("riders.rider_id"), nullable=False)
    line_type: Mapped[str] = mapped_column(String(40), nullable=False)
    trip_id: Mapped[str | None] = mapped_column(ForeignKey("trips.trip_id"), nullable=True)
    amount_rupees: Mapped[int] = mapped_column(Integer, nullable=False)


class ConversationModel(Base):
    """One conversation state per vendor rider identity."""
    __tablename__ = "conversations"

    rider_id: Mapped[str] = mapped_column(String(64), primary_key=True)
    state: Mapped[dict[str, Any]] = mapped_column(JSONB, nullable=False, default=dict)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False, server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False, server_default=func.now(), onupdate=func.now())


class InboundMessageModel(Base):
    """Deduplication key and saved response for vendor retries."""
    __tablename__ = "inbound_messages"
    __table_args__ = (
        Index("ix_inbound_messages_rider_received", "rider_id", "received_at"),
        CheckConstraint(
            "processing_status IN ('processing', 'processed', 'failed')",
            name="ck_inbound_messages_processing_status",
        ),
    )

    message_id: Mapped[str] = mapped_column(String(255), primary_key=True)
    rider_id: Mapped[str] = mapped_column(String(64), nullable=False)
    text: Mapped[str] = mapped_column(Text, nullable=False)
    received_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    reply: Mapped[str | None] = mapped_column(Text, nullable=True)
    processing_status: Mapped[str] = mapped_column(String(16), nullable=False, default="processing")
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False, server_default=func.now())


class TraceEventModel(Base):
    """Append-only audit trail returned by GET /trace/{rider_id}."""
    __tablename__ = "trace_events"
