  let fact: string;

  if (trip.status === "completed") {
    expected = tripFareRupees(trip, policy);
    fact = `Trip ${trip.tripId}: ${trip.distanceKm} km at ${trip.surgeMultiplier}x; policy fare ₹${expected}; historical trip payout ₹${paid}.`;
